mapper.select:
SELECT AA.*, AM_CHAT.`MODEL_NAME` AS modelName, AM_CHAT.`PROVIDER` AS modelProvider, CI_CHAT.`INSTANCE_NAME` AS chatInstanceName, CI_EMBED.`INSTANCE_NAME` AS embeddingInstanceName, CI_IMAGE.`INSTANCE_NAME` AS imageInstanceName, AP.`PROMPT_TITLE` AS promptTitle, ( SELECT SE.`AVATAR` FROM `SYS_EXTENSION` SE WHERE SE.`ENV_CODE` = AA.`ENV_CODE` AND (SE.`DELETED` = 0 OR SE.`DELETED` IS NULL) AND AM_CHAT.EXTENSION_CODE IS NOT NULL AND AM_CHAT.EXTENSION_CODE != '' AND (SE.EXTENSION_CODE = AM_CHAT.EXTENSION_CODE OR SE.EXTENSION_KEY = AM_CHAT.EXTENSION_CODE) ORDER BY CASE WHEN SE.EXTENSION_CODE = AM_CHAT.EXTENSION_CODE THEN 0 ELSE 1 END LIMIT 1 ) AS providerAvatar FROM `AI_AGENT` AA LEFT JOIN `AI_INSTANCE` CI_CHAT ON CI_CHAT.INSTANCE_KEY = AA.CHAT_INSTANCE_KEY AND CI_CHAT.ENV_CODE = AA.ENV_CODE AND (CI_CHAT.DELETED = 0 OR CI_CHAT.DELETED IS NULL) LEFT JOIN `AI_MODEL` AM_CHAT ON AM_CHAT.MODEL_KEY = CI_CHAT.MODEL_KEY AND AM_CHAT.ENV_CODE = AA.ENV_CODE AND (AM_CHAT.DELETED = 0 OR AM_CHAT.DELETED IS NULL) LEFT JOIN `AI_INSTANCE` CI_EMBED ON CI_EMBED.INSTANCE_KEY = AA.EMBEDDING_INSTANCE_KEY AND CI_EMBED.ENV_CODE = AA.ENV_CODE AND (CI_EMBED.DELETED = 0 OR CI_EMBED.DELETED IS NULL) LEFT JOIN `AI_INSTANCE` CI_IMAGE ON CI_IMAGE.INSTANCE_KEY = AA.IMAGE_INSTANCE_KEY AND CI_IMAGE.ENV_CODE = AA.ENV_CODE AND (CI_IMAGE.DELETED = 0 OR CI_IMAGE.DELETED IS NULL) LEFT JOIN ( SELECT ENV_CODE, PROMPT_KEY, MAX(VERSION) AS MAX_VERSION FROM `AI_PROMPT` WHERE DELETED = 0 GROUP BY ENV_CODE, PROMPT_KEY ) LATEST_P ON LATEST_P.ENV_CODE = AA.ENV_CODE AND LATEST_P.PROMPT_KEY = AA.PROMPT_KEY LEFT JOIN `AI_PROMPT` AP ON AP.PROMPT_KEY = AA.PROMPT_KEY AND AP.ENV_CODE = AA.ENV_CODE AND AP.VERSION = LATEST_P.MAX_VERSION AND (AP.DELETED = 0 OR AP.DELETED IS NULL) WHERE (AA.DELETED = 0 OR AA.DELETED IS NULL)
AND AA.ENV_CODE = #{req.envCode}
AND AA.AGENT_NAME LIKE CONCAT('%', #{req.name}, '%')
AND AA.STATUS = #{req.status}
ORDER BY AA.CREATE_TIME DESC
